-- Scheme: ayushman_bharat_pm_jay
INSERT INTO schemes (
    id, scheme_code, name, description, ministry, department,
    scheme_type, status, aliases, target_groups, tags, benefits,
    official_url, effective_from, effective_to, last_verified_at
) VALUES (
    '1077da8e-262a-5615-adb1-e8bb8da0bb4e'::uuid,
    'ayushman_bharat_pm_jay',
    'Ayushman Bharat - Pradhan Mantri Jan Arogya Yojana',
    'Ayushman Bharat - Pradhan Mantri Jan Arogya Yojana (PM-JAY) is implemented by the National Health Authority under the Ministry of Health and Family Welfare. It aims to provide cashless hospitalisation coverage of up to ₹5,00,000 per family per year for secondary and tertiary healthcare services to poor and vulnerable families. The supplied myScheme source describes rural eligibility through deprivation and automatic-inclusion criteria and urban eligibility through specified occupational categories.',
    'Ministry of Health and Family Welfare',
    'National Health Authority',
    'healthcare',
    'active',
    '["PM-JAY", "Ayushman Bharat PM-JAY", "Pradhan Mantri Jan Arogya Yojana"]'::jsonb,
    '["poor families", "vulnerable families", "rural households meeting specified deprivation criteria", "urban workers in specified occupational categories"]'::jsonb,
    '["Cashless Treatment", "Health", "Hospitalization Cover", "Insurance"]'::jsonb,
    '["Cashless hospitalisation coverage of up to ₹5,00,000 per family per year.", "Coverage is available for secondary and tertiary hospitalisation.", "Treatment costs can include consultation, medicines, diagnostics, surgery, ICU, implants, accommodation and food.", "Provides coverage for 3 days of pre-hospitalisation expenses and 15 days of post-hospitalisation expenses.", "Complications arising during treatment are covered.", "Pre-existing diseases are covered from day one.", "There is no restriction on age, gender or family size.", "Benefits are portable across India at empanelled hospitals.", "The supplied myScheme information states coverage of approximately 1,929 medical procedures."]'::jsonb,
    'https://www.pmjay.gov.in/about/pmjay',
    '2018-09-23',
    NULL,
    '2026-09-03T00:00:00Z'
) ON CONFLICT (scheme_code) DO NOTHING;

