-- Scheme: dr_syama_prasad_mookerjee_durghtana_sahayta_yojana
INSERT INTO schemes (
    id, scheme_code, name, description, ministry, department,
    scheme_type, status, aliases, target_groups, tags, benefits,
    official_url, effective_from, effective_to, last_verified_at
) VALUES (
    '8299a144-8d3e-5c1b-bb45-e3c06dfb00d6'::uuid,
    'dr_syama_prasad_mookerjee_durghtana_sahayta_yojana',
    'Dr. Syama Prasad Mookerjee Durghtana Sahayta Yojana',
    'Dr. Syama Prasad Mookerjee Durghtana Sahayta Yojana is a state-level welfare scheme of the Government of Haryana, implemented by the Social Justice and Empowerment Department. It provides financial assistance of ₹1,00,000 to individuals aged 18-70 who have suffered accidental death or disability and are not registered under Pradhan Mantri Suraksha Bima Yojana (PMSBY). The scheme is applicable only to permanent residents of Haryana who are currently residing in Haryana.',
    'Government of Haryana',
    'Social Justice and Empowerment Department',
    'benefit',
    'active',
    '["Dr. Syama Prasad Mookerjee Durghtana Sahayta Yojana", "Durghtana Sahayta Yojana"]'::jsonb,
    '["Accident victims", "Persons with disabilities", "Eligible claimants of accidental death"]'::jsonb,
    '["Accidental Assistance", "Death Compensation", "Disability", "Financial Assistance", "Haryana"]'::jsonb,
    '["₹1,00,000 for accidental death.", "₹1,00,000 for total and permanent loss of both eyes.", "₹1,00,000 for loss of both hands or both feet.", "₹1,00,000 for loss of one eye and one hand or one foot."]'::jsonb,
    'https://saralharyana.gov.in/',
    '2017-01-01',
    NULL,
    '2026-09-03T00:00:00Z'
) ON CONFLICT (scheme_code) DO NOTHING;

