-- Scheme: pm_fasal_bima_yojana
INSERT INTO schemes (
    id, scheme_code, name, description, ministry, department,
    scheme_type, status, aliases, target_groups, tags, benefits,
    official_url, effective_from, effective_to, last_verified_at
) VALUES (
    '7139f750-3c30-5c48-89c2-5fe749ccbd15'::uuid,
    'pm_fasal_bima_yojana',
    'Pradhan Mantri Fasal Bima Yojana',
    'Pradhan Mantri Fasal Bima Yojana (PMFBY) is a crop insurance scheme that provides financial protection to farmers against crop loss due to natural disasters, pests, and diseases.',
    'Ministry of Agriculture and Farmers Welfare',
    'Department of Agriculture, Cooperation and Farmers'' Welfare',
    'insurance',
    'active',
    '["PMFBY", "Pradhan Mantri Fasal Bima Yojana", "Pradhan Mantri Fasal Bima Yojna"]'::jsonb,
    '["farmers", "tenant farmers", "sharecroppers"]'::jsonb,
    '["Agriculture", "Crop", "Farmer", "Insurance", "Premium"]'::jsonb,
    '["Provides financial assistance to farmers suffering crop damage or loss arising from unforeseen events.", "Provides crop insurance coverage against specified natural disasters, pests, and diseases.", "Maximum farmer premium is 2% for Kharif food and oilseed crops, 1.5% for Rabi food and oilseed crops, and 5% for yearly commercial or horticultural crops, with the remaining premium subsidized by the government.", "Provides coverage for prevented sowing, with indemnity claims of up to a maximum of 25% of the sum insured in eligible cases.", "Provides post-harvest loss coverage for eligible crops for up to 14 days after harvesting when stored in cut-and-spread condition.", "Provides coverage for specified localized calamities such as hailstorms, landslides, and inundation.", "Uses technologies such as satellite imaging, drones, and mobile applications for crop-loss estimation and claim settlement."]'::jsonb,
    'https://pmfby.gov.in/',
    '2016-02-18',
    NULL,
    '2026-09-03T00:00:00Z'
) ON CONFLICT (scheme_code) DO NOTHING;

