    'Ministry of Agriculture and Farmers Welfare',
    'Department of Agriculture, Cooperation & Farmers'' Welfare',
    'benefit',
    'active',
    '["PM-KISAN", "PM Kisan"]'::jsonb,
    '["farmers", "landholding farmer families"]'::jsonb,
    '["Agricultural Inputs", "Agriculture", "Farmers", "Income Support", "Kisan"]'::jsonb,
    '["Eligible farmer families receive ₹6,000 per year.", "The annual benefit is paid in three equal instalments of ₹2,000 every four months.", "The benefit is transferred directly to the bank account of eligible beneficiaries through Direct Benefit Transfer (DBT)."]'::jsonb,
    'https://pmkisan.gov.in/',
    '2018-12-01',
    NULL,
    '2026-09-03T00:00:00Z'
) ON CONFLICT (scheme_code) DO NOTHING;

