-- Scheme: pm_svanidhi
INSERT INTO schemes (
    id, scheme_code, name, description, ministry, department,
    scheme_type, status, aliases, target_groups, tags, benefits,
    official_url, effective_from, effective_to, last_verified_at
) VALUES (
    '3cceaa8f-ce0d-5fc9-b569-9e1e3f10b98d'::uuid,
    'pm_svanidhi',
    'PM Street Vendor''s AtmaNirbhar Nidhi',
    'PM Street Vendor''s AtmaNirbhar Nidhi (PM SVANidhi) is a Central Sector Scheme launched on 1 June 2020 by the Ministry of Housing and Urban Affairs, Government of India. The scheme aims to formalize street vendors and enhance their economic opportunities through collateral-free working capital loans, interest subsidy and digital transaction incentives. The scheme supports vendors in restarting and expanding their businesses and promotes digital payments and financial inclusion. Street vendors include hawkers, thelewala, rehriwala, theliphadwala and others engaged in small-scale vending activities.',
    'Ministry of Housing and Urban Affairs',
    'Ministry of Housing and Urban Affairs',
    'loan_guarantee',
    'active',
    '["PM SVANidhi", "PM Street Vendor''s AtmaNirbhar Nidhi", "Street Vendor''s AtmaNirbhar Nidhi"]'::jsonb,
    '["Street Vendors", "Urban Street Vendors", "Peri-urban Street Vendors", "Rural Street Vendors vending within ULB geographical limits"]'::jsonb,
    '["Affordable Credit", "Digital Empowerment", "Enhanced Livelihood", "Street Vendors", "Working Capital Loan"]'::jsonb,
    '["First working-capital loan tranche up to ₹15,000 with repayment within 12 months.", "Second working-capital loan tranche up to ₹25,000 with repayment within 18 months.", "Third working-capital loan tranche up to ₹50,000 with repayment within 36 months.", "Next loan tranche is available on timely or early repayment.", "No prepayment penalty on early repayment.", "Interest subsidy at 7% per annum on the loan amount.", "Interest subsidy is credited quarterly to the beneficiary''s bank account.", "Interest subsidy is applicable only for standard (non-NPA) accounts.", "Interest subsidy is valid up to 31 March 2033.", "Cashback up to ₹100 per month for digital transactions.", "Credit guarantee cover of 31.87% for the first tranche loan.", "Credit guarantee cover of 8.25% for the second tranche loan.", "Credit guarantee cover of 6% for the third tranche loan.", "No credit guarantee charges for lending institutions.", "UPI-linked RuPay credit card with initial credit limit of ₹10,000, extendable up to ₹30,000.", "UPI-linked RuPay credit card has a validity of 5 years.", "UPI-linked RuPay credit card is available after successful repayment of the second loan tranche."]'::jsonb,
    'https://pmsvanidhi.mohua.gov.in/',
    '2020-06-01',
    NULL,
    '2026-09-03T00:00:00Z'
) ON CONFLICT (scheme_code) DO NOTHING;

INSERT INTO scheme_rules (
    id, scheme_id, rule_group, field, operator, value, description, rule_purpose
) VALUES (
    '3b9fde38-7914-594c-a45e-67b373054e66'::uuid,
    '3cceaa8f-ce0d-5fc9-b569-9e1e3f10b98d'::uuid,
    'vendor_identification',
    'meets_pm_svanidhi_vendor_identification_criteria',
    '=',
    'true'::jsonb,
    'Applicant must satisfy at least one of the source-supported vendor identification conditions: (1) Street vendor possessing a Certificate of Vending or Identity Card issued by an Urban Local Body (ULB). (2) Vendor identified in the survey but not yet issued a Certificate of Vending or Identity Card. (3) Street vendor left out of the ULB-led identification survey or who started vending after completion of the survey and has a Letter of Recommendation (LoR) from the ULB or Town Vending Committee (TVC). (4) Vendor from surrounding development, peri-urban or rural areas vending within the geographical limits of a ULB and possessing an LoR issued by the ULB or TVC.',
    'eligibility'
) ON CONFLICT (id) DO NOTHING;

