    id, scheme_code, name, description, ministry, department,
    scheme_type, status, aliases, target_groups, tags, benefits,
    official_url, effective_from, effective_to, last_verified_at
) VALUES (
    '664e31c2-4eb7-5d6d-b710-eb71f37551ed'::uuid,
    'pm_usp_central_sector_scholarship',
    'Pradhan Mantri Uchchatar Shiksha Protsahan (PM-USP) Central Sector Scheme of Scholarship for College and University Students',
    'The PM-USP Central Sector Scheme of Scholarship for College and University Students is a scholarship scheme of the Department of Higher Education, Ministry of Education. Its primary objective is to provide financial assistance to meritorious students from poor families, helping them meet part of their day-to-day expenses while pursuing higher studies. Scholarships are awarded based on the results of the Higher Secondary / Class 12th Board Examination, with a maximum of 82,000 fresh scholarships per annum. The scheme supports Graduate and Postgraduate degrees in colleges and universities, as well as professional courses such as Medical and Engineering.',
    'Ministry of Education',
    'Department of Higher Education',
    'scholarship',
    'active',
    '["PM-USP", "PM-USP Central Sector Scheme of Scholarship", "Central Sector Scheme of Scholarship for College and University Students", "CSSS", "Central Sector Scheme of Scholarship"]'::jsonb,
    '["meritorious students", "students from poor families", "college students", "university students", "undergraduate students", "postgraduate students", "students pursuing professional courses", "students pursuing technical courses"]'::jsonb,
    '["College", "Financial Assistance", "Scholarship", "Student", "University"]'::jsonb,
    '["₹12,000 per annum at the Graduation level for the first three years of College and University courses.", "₹20,000 per annum at the Post-graduation level.", "₹20,000 per annum in the 4th and 5th year for students pursuing professional courses where the course duration is five years or an integrated course.", "Students pursuing technical courses such as B.Tech and B.Engg. receive scholarship up to graduation level only: ₹12,000 per annum for the 1st year, ₹12,000 per annum for the 2nd year, ₹12,000 per annum for the 3rd year, and ₹20,000 in the 4th year.", "Scholarship is disbursed directly into the Aadhaar-seeded bank account of the beneficiary through Direct Benefit Transfer (DBT)."]'::jsonb,
    'https://scholarships.gov.in/',
    '2008-06-01',
    NULL,
    '2026-09-03T00:00:00Z'
) ON CONFLICT (scheme_code) DO NOTHING;

