-- Scheme: pmay_gramin
INSERT INTO schemes (
    id, scheme_code, name, description, ministry, department,
    scheme_type, status, aliases, target_groups, tags, benefits,
    official_url, effective_from, effective_to, last_verified_at
) VALUES (
    'a963ce45-4630-5b97-9f82-323e67aa4f4d'::uuid,
    'pmay_gramin',
    'Pradhan Mantri Awaas Yojana - Gramin',
    'Pradhan Mantri Awaas Yojana - Gramin (PMAY-G) is a flagship rural housing scheme of the Ministry of Rural Development that aims to provide pucca houses with basic amenities to eligible rural households. The eligible universe is determined through SECC data and comprises houseless households and households living in zero, one, or two-room houses with kutcha walls and kutcha roofs, subject to a defined exclusion process.',
    'Ministry of Rural Development',
    'Ministry of Rural Development',
    'housing',
    'active',
    '["PMAY-G", "PMAY Gramin", "Pradhan Mantri Awaas Yojana Gramin"]'::jsonb,
    '["houseless rural households", "households living in kutcha houses", "households living in dilapidated houses", "SC/ST households", "minority households", "persons with disabilities", "other eligible rural households"]'::jsonb,
    '["Financial Assistance", "Housing", "Loan", "Rural Development"]'::jsonb,
    '["Financial assistance of ₹1,20,000 per unit for plain areas.", "Financial assistance of ₹1,30,000 per unit for hilly areas, difficult areas and IAP districts, including Himalayan states, North-Eastern states and UT of Jammu & Kashmir.", "Willing beneficiaries can avail institutional finance up to ₹70,000 at 3% lower interest rate.", "Maximum principal amount for which subsidy can be sought is ₹2,00,000.", "Minimum house size 25 sq m including dedicated hygienic cooking area.", "Up to ₹12,000 assistance for toilets through convergence with SBM-G.", "MGNREGA convergence: employment as unskilled labour at ₹90.95/day for 95 days as stated by the supplied source.", "One LPG connection per house through PM Ujjwala convergence.", "Convergence for piped drinking water, electricity, clean and efficient cooking fuel and waste management.", "Electronic payments directly to Aadhaar-linked bank/post-office accounts."]'::jsonb,
    'https://pmayg.dord.gov.in/netiayHome/home.aspx',
    '2016-04-01',
    NULL,
    '2026-09-03T00:00:00Z'
) ON CONFLICT (scheme_code) DO NOTHING;

INSERT INTO scheme_rules (
    id, scheme_id, rule_group, field, operator, value, description, rule_purpose
) VALUES (
    'b4a5579b-4880-508b-a61d-f4c56c288575'::uuid,
    'a963ce45-4630-5b97-9f82-323e67aa4f4d'::uuid,
    'entitlement',
    'meets_pmay_g_entitlement_criteria',
    '=',
    'true'::jsonb,
    'Applicant household must be part of the eligible universe as determined through SECC data. The eligible universe consists of houseless households and households living in zero, one, or two-room houses with kutcha walls and kutcha roofs, subject to the defined exclusion process. Automatic or compulsory inclusion covers: (1) households without shelter, (2) destitute or living on alms, (3) manual scavengers, (4) primitive tribal groups, and (5) legally released bonded labourers. Deprivation and prioritisation criteria — including no adult member between 16 and 59, female-headed household with no adult male member between 16 and 59, no literate adult above 25, disabled member with no able-bodied adult, and landless household deriving major income from manual casual labour — are used for prioritisation and not as mandatory AND eligibility rules.',
    'eligibility'
) ON CONFLICT (id) DO NOTHING;

