-- Scheme: pmay_urban
INSERT INTO schemes (
    id, scheme_code, name, description, ministry, department,
    scheme_type, status, aliases, target_groups, tags, benefits,
    official_url, effective_from, effective_to, last_verified_at
) VALUES (
    'a2310e0d-9781-5b13-8087-efb0ae714ad5'::uuid,
    'pmay_urban',
    'Pradhan Mantri Awas Yojana - Urban',
    'Pradhan Mantri Awas Yojana - Urban (PMAY-U) was launched on 25 June 2015 by the Ministry of Housing & Urban Affairs, Government of India with the vision of Housing for All. The scheme provides pucca houses to eligible urban households, addressing urban housing shortages especially for EWS, LIG and MIG categories, including slum dwellers. The mission covers statutory towns and notified urban areas as per Census 2011. Aadhaar is mandatory for eligible beneficiaries.',
    'Ministry of Housing & Urban Affairs',
    'Ministry of Housing & Urban Affairs',
    'housing',
    'active',
    '["PMAY-U", "PMAY Urban", "Pradhan Mantri Awas Yojana Urban", "PMAY-U 2.0"]'::jsonb,
    '["EWS", "LIG", "MIG", "urban households", "slum dwellers"]'::jsonb,
    '["Housing", "Loan", "Rehabilitation", "Sanitation", "Urban"]'::jsonb,
    '["BLC & AHP: Central Government assistance varies by State/UT. For Assam, Arunachal Pradesh, Meghalaya, Manipur, Mizoram, Nagaland, Tripura, Sikkim, Himachal Pradesh, Uttarakhand, UTs of Jammu and Kashmir, Puducherry and Delhi: Central Government ₹2.25 lakh per unit and State Government minimum ₹0.25 lakh per unit. For all other UTs: Central Government ₹2.50 lakh per unit. For all other States: Central Government ₹1.5 lakh per unit and State Government minimum ₹1.00 lakh per unit.", "ARH: Technology Innovation Grant of ₹3,000 per square metre per unit from the Central Government and ₹2,000 per square metre per unit from the State Government, as stated in the supplied source.", "ISS: Home Loan Subsidy of up to ₹1.80 lakh actual release per unit by the Government of India as a Central Sector Scheme."]'::jsonb,
    'https://pmay-urban.gov.in/',
    '2015-06-25',
    NULL,
    '2026-09-03T00:00:00Z'
) ON CONFLICT (scheme_code) DO NOTHING;

