-- Scheme: pmjjby
INSERT INTO schemes (
    id, scheme_code, name, description, ministry, department,
    scheme_type, status, aliases, target_groups, tags, benefits,
    official_url, effective_from, effective_to, last_verified_at
) VALUES (
    '329c07ec-0bef-56b0-8a0f-2f0ede225b1e'::uuid,
    'pmjjby',
    'Pradhan Mantri Jeevan Jyoti Bima Yojana',
    'Pradhan Mantri Jeevan Jyoti Bima Yojana (PMJJBY) is a life insurance scheme offering term life insurance cover for death due to any reason. It is a one-year cover, renewable year to year, offered by banks and post offices and administered through life insurance companies. Individuals who are account holders of participating banks or post offices and are aged 18 to 50 years are entitled to join.',
    'Ministry of Finance',
    'Ministry of Finance',
    'insurance',
    'active',
    '["PMJJBY", "Pradhan Mantri Jeevan Jyoti Bima Yojana"]'::jsonb,
    '["bank account holders", "post office account holders"]'::jsonb,
    '["Life Insurance", "Insurance", "Financial Security", "Bank Account", "Social Security"]'::jsonb,
    '["One-year term life cover of ₹2,00,000 for subscribers aged 18-50 years.", "Death due to any reason is covered under the scheme.", "Premium is ₹436 per annum per subscriber, auto-debited from the subscriber''s bank or post office account."]'::jsonb,
    'https://jansuraksha.gov.in/',
    '2015-05-01',
    NULL,
    '2026-09-03T00:00:00Z'
) ON CONFLICT (scheme_code) DO NOTHING;

