    id, scheme_code, name, description, ministry, department,
    scheme_type, status, aliases, target_groups, tags, benefits,
    official_url, effective_from, effective_to, last_verified_at
) VALUES (
    '9a6d9a9e-6f6d-593d-aa3a-a443fe3b040f'::uuid,
    'pmkvy_4_short_term_training',
    'Pradhan Mantri Kaushal Vikas Yojana 4.0 - Short-Term Training',
    'Pradhan Mantri Kaushal Vikas Yojana 4.0 - Short-Term Training is a skill development scheme implemented between FY 2022-2026 under the Skill India Programme. Implemented by the Ministry of Skill Development and Entrepreneurship (MSDE), Government of India, it provides market-oriented and demand-driven skill training to youth to enhance employability through industry-relevant, NSQF-aligned courses. The training ranges between 300 and 600 hours with an inherent On-the-Job Training component. Higher-duration courses and higher-level NSQF job roles including levels 5, 6 and above are covered. The scheme includes assessment and certification, accidental insurance, applicable allowances and support. NSDC is the implementing arm of MSDE and the designated Central Nodal Agency.',
    'Ministry of Skill Development and Entrepreneurship',
    'Ministry of Skill Development and Entrepreneurship',
    'benefit',
    'active',
    '["PMKVY 4.0", "Pradhan Mantri Kaushal Vikas Yojana 4.0", "PMKVY 4.0 - Short-Term Training", "Short-Term Training (STT)"]'::jsonb,
    '["youth", "unemployed youth", "out-of-education candidates", "school/college dropouts", "candidates seeking fresh skilling", "candidates seeking re-skilling", "candidates seeking upskilling", "Indian nationals"]'::jsonb,
    '["Counselling", "Dropout", "Kaushal", "Placement", "Skill", "Training", "Unemployed", "Vikas"]'::jsonb,
    '["Free NSQF-aligned skill training ranging between 300 and 600 hours.", "Higher-duration courses may also be offered where justified by industry or sectoral demand.", "Training in higher-level NSQF job roles, including NSQF levels 5, 6 and above.", "On-the-Job Training (OJT) is an inherent component of the training and provides practical exposure and a live-work environment.", "OJT duration is guided by the approved Qualification Pack.", "An induction kit is provided including a T-shirt for male candidates, a jacket for female candidates, and a bag.", "Uniform, induction kit and participant handbook are covered up to a maximum of ₹500 per candidate.", "Assessment and certification are provided.", "₹600 per candidate per assessment is paid to Sector Skill Councils (SSCs) or Awarding Bodies for overseeing and facilitating final assessments.", "Every candidate gets one free reassessment opportunity.", "Reassessment fees are borne by the scheme.", "Accidental insurance with one year of coverage is provided to every certified candidate at the applicable rate of ₹14.16.", "Boarding and lodging with transport facilities are provided to special groups including women, Persons with Disability (PwD), and candidates in Special Areas as defined in Common Norms.", "Boarding, lodging and transport support may also be extended to Aspirational districts, Border districts, Tribal-dominated districts and LWE-affected districts.", "Conveyance or transportation cost is permissible for women and PwD candidates in case of non-residential training, according to Common Norms.", "Additional support of ₹5,000 is provided to PwD candidates towards assistive devices, aids and appliances.", "A free printed certificate is provided after successful certification.", "A QR-code-based digital certificate is issued through DigiLocker.", "A digital certificate or download link is also provided through email or phone.", "The certificate is available through the Skill India Digital profile.", "A convocation ceremony is held for passed-out candidates.", "After certification, candidates are tracked for one year.", "Candidates are linked with Rojgar Melas and Apprenticeship Melas.", "Skill India Digital provides access to jobs and apprenticeship opportunities.", "Skill India Digital also provides access to other facilities including loans for entrepreneurship.", "A post-certification tracking allowance of up to ₹50 per certified candidate is utilised for post-certification tracking.", "On passing the assessment, candidates receive a graded certificate.", "For NSQF Levels 1, 2 and 3: Grade A is 85% and above, Grade B is 70% to less than 85%, Grade C is 50% to 70%.", "For NSQF Level 4 and above: Grade A is 85% and above, Grade B is 70% to less than 85%.", "More than 70% biometric AEBAS attendance is required for a candidate to appear in the assessment.", "Indicative average per-candidate cost is ₹9,540 for a 300-hour STT course including Skill Hubs.", "Indicative average per-candidate cost is ₹13,724 for a 450-hour STT course.", "These costs are derived using a base training cost of ₹27.89 per hour.", "Funds are released to Training Providers, Training Centres and Skill Hubs in three tranches: 30% on commencement, 30% when the batch achieves 70% AEBAS attendance once and 50% of training is over, and 40% on certification of passed candidates only.", "Accidental insurance coverage is valid for one year.", "Post-certification tracking is conducted for one year from the certification date."]'::jsonb,
    'https://www.skillindiadigital.gov.in/home',
    '2022-04-01',
    NULL,
    '2026-09-03T00:00:00Z'
) ON CONFLICT (scheme_code) DO NOTHING;

