INSERT INTO schemes (
    id, scheme_code, name, description, ministry, department,
    scheme_type, status, aliases, target_groups, tags, benefits,
    official_url, effective_from, effective_to, last_verified_at
) VALUES (
    '9ddca41e-f34f-516f-bf83-48f944a120d7'::uuid,
    'pmmvy',
    'Pradhan Mantri Matru Vandana Yojana',
    'Pradhan Mantri Matru Vandana Yojana (PMMVY) is a Centrally Sponsored flagship scheme of the Ministry of Women and Child Development designed to provide maternity benefits to pregnant women and lactating mothers belonging to socially and economically disadvantaged sections. PMMVY 2.0, implemented under Mission Shakti and effective from 01 April 2022, provides an additional incentive of ₹6,000 in one instalment for the second child if the second child is a girl.',
    'Ministry of Women and Child Development',
    'Ministry of Women and Child Development',
    'benefit',
    'active',
    '["PMMVY", "PMMVY 2.0", "Pradhan Mantri Matru Vandana Yojana 2.0"]'::jsonb,
    '["pregnant women", "lactating mothers", "socially disadvantaged women", "economically disadvantaged women"]'::jsonb,
    '["Cash Incentive", "Financial Assistance", "Good Nutrition", "Maternity Benefit", "Pregnant Women"]'::jsonb,
    '["First child: ₹5,000 total PMMVY maternity benefit in two instalments, with the source stating the beneficiary may also receive JSY cash incentive after institutional delivery so that on average a woman receives ₹6,000.", "First instalment: ₹3,000 on registration of pregnancy and at least one antenatal check-up within six months from LMP at an Anganwadi Centre or approved health facility.", "Second instalment: ₹2,000 after childbirth registration and after the child receives all due vaccines up to 14 weeks as admissible under the Universal Immunization Programme.", "Second child if the second child is a girl: ₹6,000 in one instalment after birth, subject to pregnancy registration, ANC within six months from LMP, girl-child birth registration and due vaccinations up to 14 weeks.", "In case of miscarriage or stillbirth, the beneficiary is treated as a fresh beneficiary for any future pregnancy.", "The scheme aims to promote positive behavioural change towards the girl child and contribute to improving Sex Ratio at Birth."]'::jsonb,
    'https://pmmvy.wcd.gov.in/',
    '2022-04-01',
    NULL,
    '2026-09-03T00:00:00Z'
) ON CONFLICT (scheme_code) DO NOTHING;

