-- Scheme: pradhan_mantri_jan_dhan_yojana
INSERT INTO schemes (
    id, scheme_code, name, description, ministry, department,
    scheme_type, status, aliases, target_groups, tags, benefits,
    official_url, effective_from, effective_to, last_verified_at
) VALUES (
    '3d208187-a37b-54bd-aac9-a4bf1e69d4e4'::uuid,
    'pradhan_mantri_jan_dhan_yojana',
    'Pradhan Mantri Jan Dhan Yojana',
    'Pradhan Mantri Jan Dhan Yojana (PMJDY) is a National Mission for Financial Inclusion launched across India in August 2014. The scheme aims to provide universal banking services and financial inclusion, including basic savings bank accounts, access to need-based credit, remittances, insurance and pension services. Beyond 14.08.2018, the focus shifted from opening accounts for every household to every unbanked adult.',
    'Ministry of Finance',
    'Department of Financial Services',
    'benefit',
    'active',
    '["PMJDY", "Pradhan Mantri Jan Dhan Yojana", "Jan Dhan Yojana"]'::jsonb,
    '["Unbanked adults", "Indian citizens", "Weaker sections", "Low-income groups"]'::jsonb,
    '["Bank", "Chota Khata", "Insurance", "Jan Dhan", "Financial Inclusion", "Savings Account"]'::jsonb,
    '["Basic Savings Bank Deposit Account (BSBDA) with no minimum balance requirement.", "Account holders can use bank branches, ATMs and Banking Correspondents for depositing and withdrawing cash.", "Under the supplied source, cash withdrawal from the BSBDA is limited to four times a month.", "Small Account or Chota Khata can be opened without presenting legal documents, subject to the source''s stated conditions.", "Small Accounts are normally valid for twelve months and can continue for another twelve months if the account holder provides a document showing that they applied for an Officially Valid Document within the first twelve months.", "Free RuPay debit card with built-in accidental insurance cover of ₹2 lakh for beneficiaries.", "Accounts opened before 28.08.2018 have the ₹1 lakh accidental insurance cover stated by the source.", "Overdraft facility up to ₹10,000.", "Banking Correspondents or Bank Mitras provide banking services including savings, deposits, payments, withdrawals and mini account statements, particularly in remote or rural areas.", "PMJDY facilitates access to financial services including savings, credit, remittances, insurance and pension."]'::jsonb,
    'https://pmjdy.gov.in/',
    '2014-08-28',
    NULL,
    '2026-09-03T00:00:00Z'
) ON CONFLICT (scheme_code) DO NOTHING;

