    'pradhan_mantri_mudra_yojana',
    'Pradhan Mantri Mudra Yojana',
    'Pradhan Mantri Mudra Yojana (PMMY) is a flagship Government of India scheme facilitating micro credit or loans up to ₹20 lakh to income-generating micro enterprises in the non-farm sector, including manufacturing, trading, services and activities allied to agriculture such as poultry, dairy and beekeeping. Loans are provided through eligible Member Lending Institutions including public sector banks, private sector banks, state-operated cooperative banks, regional rural banks, MFIs, NBFCs, small finance banks and other approved financial intermediaries.',
    'Ministry of Finance',
    'Department of Financial Services',
    'loan_guarantee',
    'active',
    '["PMMY", "Pradhan Mantri Mudra Yojana", "MUDRA"]'::jsonb,
    '["Micro entrepreneurs", "Small business owners", "Manufacturing units", "Trading enterprises", "Service providers", "Agriculture-allied activity operators"]'::jsonb,
    '["Business", "Loan", "MUDRA", "Micro Enterprise", "Entrepreneurship", "Manufacturing", "Trading", "Services"]'::jsonb,
    '["Shishu loans covering loans up to ₹50,000.", "Kishore loans above ₹50,000 and up to ₹5 lakh.", "Tarun loans above ₹5 lakh and up to ₹10 lakh.", "Tarun Plus loans up to ₹20 lakh for entrepreneurs who have successfully repaid previous loans under the Tarun category.", "Interest rates are determined by Member Lending Institutions according to applicable RBI guidelines.", "Upfront fee or processing charges for Shishu loans are waived by most banks according to the supplied source."]'::jsonb,
    'https://www.mudra.org.in/',
    '2015-04-08',
    NULL,
    '2026-09-03T00:00:00Z'
) ON CONFLICT (scheme_code) DO NOTHING;

