-- Scheme: pradhan_mantri_ujjwala_yojana_2
INSERT INTO schemes (
    id, scheme_code, name, description, ministry, department,
    scheme_type, status, aliases, target_groups, tags, benefits,
    official_url, effective_from, effective_to, last_verified_at
) VALUES (
    '77f081d4-860f-59e7-8292-235032768758'::uuid,
    'pradhan_mantri_ujjwala_yojana_2',
    'Pradhan Mantri Ujjwala Yojana 2.0',
    'Pradhan Mantri Ujjwala Yojana (PMUY) was launched in May 2016 by the Ministry of Petroleum and Natural Gas to provide free LPG connections to women from poor households. The objective is to promote clean cooking fuel such as LPG among rural and deprived families traditionally relying on firewood, coal or cow-dung cakes. Under Ujjwala 2.0, the scheme was expanded with an additional allocation of 1.6 crore LPG connections, including a special facility for migrant households.',
    'Ministry of Petroleum and Natural Gas',
    'Ministry of Petroleum and Natural Gas',
    'benefit',
    'active',
    '["PMUY", "PMUY 2.0", "Pradhan Mantri Ujjwala Yojana", "Pradhan Mantri Ujjwala Yojana 2.0"]'::jsonb,
    '["Women", "Poor households", "Rural households", "Deprived households", "Migrant households"]'::jsonb,
    '["Cooking Fuel", "Household", "LPG", "Women", "Clean Cooking Fuel"]'::jsonb,
    '["Government cash assistance of ₹1,600 for a 14.2 kg LPG connection.", "Government cash assistance of ₹1,150 for a 5 kg LPG connection.", "Security deposit of cylinder is covered: ₹1,250 for a 14.2 kg cylinder or ₹800 for a 5 kg cylinder.", "Pressure regulator cost of ₹150 is covered.", "LPG hose cost of ₹100 is covered.", "Domestic Gas Consumer Card cost of ₹25 is covered.", "Inspection, installation and demonstration charges of ₹75 are covered.", "First LPG refill is provided free of cost.", "Stove or hotplate is provided free of cost.", "Deposit-free LPG connection is provided to eligible PMUY beneficiaries."]'::jsonb,
    'https://www.pmuy.gov.in/',
    '2016-05-01',
    NULL,
    '2026-09-03T00:00:00Z'
) ON CONFLICT (scheme_code) DO NOTHING;

